function validate([s]) {
  if (typeof s !== 'string' || s.length < 3 || s.length > 200) return 's must be 3 to 200 characters long.';
  if (!/^[a-z0-9 ]+$/.test(s)) return 's may contain only lowercase letters, digits and spaces.';
  const tokens = s.split(' ');
  if (tokens.length < 2 || tokens.length > 100) return 's needs 2 to 100 tokens.';
  if (tokens.some(t => t === '')) return 'Tokens are separated by single spaces with none at the ends.';
  if (tokens.some(t => !/^[a-z]+$/.test(t) && !/^[1-9][0-9]?$/.test(t))) return 'Each token is a lowercase word or a number from 1 to 99 without leading zeros.';
  if (tokens.filter(t => /^[0-9]/.test(t)).length < 2) return 's needs at least two numbers.';
  return null;
}

