function areNumbersAscending(s) {
  let previous = 0;
  for (const token of s.split(' ')) {
    if (token[0] >= '0' && token[0] <= '9') {
      const value = Number(token);
      if (value <= previous) {
        return false;
      }
      previous = value;
    }
  }
  return true;
}

