function generate(rand, size) {
  const large = size === 'large';
  const tokenCount = large ? 40 + Math.floor(rand() * 60) : 2 + Math.floor(rand() * 7);
  const numberShare = 0.2 + rand() * 0.7;
  const isNumber = Array.from({ length: tokenCount }, () => rand() < numberShare);
  isNumber[0] = isNumber[0] || rand() < 0.5;
  let count = isNumber.filter(Boolean).length;
  for (let i = tokenCount - 1; count < 2; i--) if (!isNumber[i]) { isNumber[i] = true; count++; }
  // Numbers: a strictly increasing run, a run with one flaw, or random values.
  const mode = rand();
  const pool = Array.from({ length: 99 }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  let values = pool.slice(0, count).sort((a, b) => a - b);
  if (mode < 0.3) {
    const k = Math.floor(rand() * (count - 1));
    if (rand() < 0.5) values[k + 1] = values[k]; else [values[k], values[k + 1]] = [values[k + 1], values[k]];
  } else if (mode < 0.5) {
    const top = large ? 99 : 12;
    values = values.map(() => 1 + Math.floor(rand() * top));
  }
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const word = () => Array.from({ length: 1 + Math.floor(rand() * (large ? 3 : 5)) }, () => letters[Math.floor(rand() * 26)]).join('');
  let next = 0;
  const tokens = isNumber.map(numeric => numeric ? String(values[next++]) : word());
  const kinds = isNumber.slice();
  // Trim to 200 characters, never dropping below two numbers.
  let length = tokens.join(' ').length;
  while (length > 200) {
    const i = Math.floor(rand() * tokens.length);
    if (kinds[i] && kinds.filter(Boolean).length <= 2) continue;
    length -= tokens[i].length + 1;
    tokens.splice(i, 1);
    kinds.splice(i, 1);
  }
  return [tokens.join(' ')];
}
